<script setup lang="ts">
import {defineAsyncComponent,reactive} from 'vue'
import {quality} from '../api/quality'
import {useQualityReports} from '../hooks/useQualityReports'
import Metrics from './QualityMetrics.vue'
const props=defineProps<{level?:number;overview?:boolean}>(),vm=reactive(useQualityReports(props.level)),Detail=defineAsyncComponent(()=>import('../shared/components/QualityDetail.vue'))
</script>
<template><a-card :title="overview?'品质首页':(level===1?'公司':'项目')+'品质报表'"><template #extra><a-space><a-button @click="vm.load" :loading="vm.loading">刷新</a-button><a-button v-if="vm.can('quality-work-order','export')" @click="vm.exportRows">导出当前报表</a-button></a-space></template><a-alert v-if="vm.error" :message="vm.error" type="error" show-icon /><a-alert v-if="vm.success" :message="vm.success" type="success" show-icon />
