 <Metrics :summary="vm.summary" /><a-tabs v-model:activeKey="vm.group"><a-tab-pane key="project" tab="项目统计" /><a-tab-pane key="line" tab="条线统计" /><a-tab-pane key="problems" tab="问题明细" /></a-tabs>
 <a-table v-if="vm.group!=='problems'" :data-source="vm.rows" :columns="vm.columns" :loading="vm.loading" :row-key="(r:Record<string,string|number>)=>String(r.projectId)+':'+String(r.lineId)" :scroll="{x:'max-content'}" />
 <a-table v-else :data-source="vm.problems" :loading="vm.loading" row-key="id" :pagination="{current:vm.current,total:vm.total,pageSize:20,showSizeChanger:false}" :scroll="{x:'max-content'}" @change="(p:{current?:number})=>{vm.current=p.current||1;vm.load()}"><a-table-column title="项目" data-index="projectName" /><a-table-column title="条线" data-index="subjectParentName" /><a-table-column title="科目" data-index="subjectName" /><a-table-column title="检查项" data-index="checkContentName" /><a-table-column title="问题描述" data-index="checkResult" /><a-table-column title="扣分标准" data-index="deductionStandard" /><a-table-column title="核查人" data-index="executorName" /><a-table-column title="得分" data-index="score" /><a-table-column title="操作" key="actions"><template #default="{record}"><a-button type="link" @click="vm.showDetail(record)">查看工单</a-button></template></a-table-column></a-table>
